#if LOCAL_SCENE3_AUDIT
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class GuiziPreview{static double next;static GuiziPreview(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+5;if(EditorApplication.isUpdating||EditorApplication.isCompiling||!File.Exists("D:/-11-scene3-audit/guizi-fixed.txt")||File.Exists("D:/-11-scene3-audit/guizi2-after.png"))return;var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.name!="scene3")return;try{foreach(var r in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name=="guizi1"||r.name=="guizi2")){var go=new GameObject("Cabinet preview"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();cam.enabled=false;cam.transform.position=r.bounds.center+new Vector3(.85f,.18f,-.35f);cam.transform.LookAt(r.bounds.center);cam.fieldOfView=48;cam.nearClipPlane=.015f;cam.farClipPlane=30;cam.allowHDR=true;var v=go.AddComponent<Scene3ColorView>();v.viewShader=Shader.Find("BlenderScene3/ColorView");var rt=RenderTexture.GetTemporary(700,700,24,RenderTextureFormat.ARGBHalf);var active=RenderTexture.active;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var im=new Texture2D(700,700,TextureFormat.RGB24,false);im.ReadPixels(new Rect(0,0,700,700),0,0);if(!rt.sRGB){var px=im.GetPixels();for(int j=0;j<px.Length;j++)px[j]=px[j].gamma;im.SetPixels(px);}im.Apply();File.WriteAllBytes("D:/-11-scene3-audit/"+r.name+"-after.png",im.EncodeToPNG());UnityEngine.Object.DestroyImmediate(im);}finally{RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}}catch(Exception e){File.WriteAllText("D:/-11-scene3-audit/guizi-preview-error.txt",e.ToString());}}}

#endif
